// ═══════════════════════════════════════════════
// Renderiza el template reemplazando {placeholders}
// ═══════════════════════════════════════════════
const ctx = $input.item.json;
const cfg = $('Config').first().json;

const testMode  = cfg.TEST_MODE === true;
const testEmail = cfg.TEST_EMAIL;

// Formatea total como 'USD 1.234,56'
const fmtUSD = (n) => {
  if (n === null || n === undefined || n === '') return '';
  const num = Number(n);
  if (Number.isNaN(num)) return '';
  return 'USD ' + num.toLocaleString('es-AR', {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2
  });
};

const replacements = {
  '{cliente}':              ctx.cliente_nombre       || '',
  '{contacto}':             ctx.cliente_contacto     || 'equipo',
  '{nro_pedido}':           ctx.nro_pedido           || '—',
  '{nro_remito}':           ctx.nro_remito           || '—',
  '{pieza}':                'los productos',
  '{fecha_entrega_desde}':  ctx.fecha_entrega_desde  || '',
  '{fecha_entrega_hasta}':  ctx.fecha_entrega_hasta  || '',
  '{total}':                fmtUSD(ctx.total),
  '{condicion_pago}':       ctx.condicion_pago       || '',
  '{catalogo_url}':         ctx.catalogo_url         || 'https://vitalmetsa.com'
};

let subject = ctx.template_subject || '';
let body    = ctx.template_body    || '';

for (const [key, value] of Object.entries(replacements)) {
  subject = subject.split(key).join(value);
  body    = body.split(key).join(value);
}

// En test mode redirigir + marcar el asunto
const toEmail       = testMode ? testEmail : ctx.cliente_email;
const subjectFinal  = testMode
  ? `[TEST -> ${ctx.cliente_email}] ${subject}`
  : subject;

return {
  json: {
    ...ctx,
    to_email:          toEmail,
    rendered_subject:  subjectFinal,
    rendered_body:     body,
    is_test:           testMode
  }
};
